<div class="grid two"><section class="panel"><h2>Nova resposta rápida</h2><form method="post" action="/painel/respostas-rapidas"><input type="hidden" name="csrf" value="<?=consoleE($data['csrf'])?>"><input type="hidden" name="action" value="save_quick_reply"><div class="field"><label for="reply-name">Atalho</label><input id="reply-name" name="name" maxlength="80" required placeholder="Horário de atendimento"></div><div class="field"><label for="reply-body">Mensagem</label><textarea id="reply-body" name="body" maxlength="4096" required placeholder="Olá! Nosso atendimento funciona de segunda a sexta..."></textarea></div><button class="btn" type="submit" <?=!$active?'disabled':''?>>Salvar resposta rápida</button></form></section><section class="panel"><h2>Respostas disponíveis no chat</h2><div class="replylist"><?php foreach(($data['quick_replies']??[]) as $r): ?><article class="reply"><div><b><?=consoleE($r['name'])?></b><p><?=consoleE($r['body'])?></p></div><form method="post" action="/painel/respostas-rapidas" onsubmit="return confirm('Remover esta resposta rápida?')"><input type="hidden" name="csrf" value="<?=consoleE($data['csrf'])?>"><input type="hidden" name="action" value="delete_quick_reply"><input type="hidden" name="reply_id" value="<?=(int)$r['id']?>"><button class="btn danger" type="submit" <?=!$active?'disabled':''?>>Remover</button></form></article><?php endforeach; ?><?php if(empty($data['quick_replies'])): ?><div class="empty"><b>Nenhuma resposta rápida</b>Crie uma mensagem recorrente para inserir no chat.</div><?php endif; ?></div></section></div>
<?php endif; ?>
</main><footer style="text-align:center;color:#728279;font-size:.76rem;padding:0 12px 24px">ZapApi · API oficial WhatsApp Cloud · Dados isolados por empresa</footer></div></div>
<?php if($page==='inbox'): ?><script>
(function(){
  var rowsBox=document.querySelector('.convrows'),stream=document.getElementById('message-stream'),soundButton=document.getElementById('sound-toggle');
  var accountSelect=document.getElementById('account-filter'),feedback=document.getElementById('live-feedback');
  if(!rowsBox)return;
  var params=new URLSearchParams(window.location.search),accountId=accountSelect?accountSelect.value:(params.get('account_id')||''),selectedWa=params.get('wa_id')||'';
  var seenMessages=new Set(Array.from(rowsBox.querySelectorAll('[data-message-id]')).map(function(row){return row.dataset.messageId;}));
  var conversationSignature='',messageSignature='',refreshing=false,sending=false;
  var knownMessageIds=new Set(Array.from(stream?stream.querySelectorAll('[data-message-id]'):[]).map(function(item){return item.dataset.messageId;}));
  var AudioContextType=window.AudioContext||window.webkitAudioContext,audioContext=null,audioReady=false,soundEnabled=true;
  try{soundEnabled=window.localStorage.getItem('zapapi-chat-sounds')!=='off';}catch(error){}
  function updateSoundButton(){if(!soundButton)return;soundButton.textContent=!soundEnabled?'🔕 Som desligado':audioReady?'🔔 Som ligado':'🔔 Ativar som';soundButton.setAttribute('aria-pressed',soundEnabled?'true':'false');soundButton.setAttribute('aria-label',!soundEnabled?'Ativar sons de notificação':audioReady?'Desativar sons de notificação':'Ativar sons de notificação');soundButton.title=!soundEnabled?'Ativar sons de notificação':audioReady?'Desativar sons de notificação':'Ativar reprodução de áudio neste navegador';}
  function unlockAudio(){if(!soundEnabled||!AudioContextType)return Promise.resolve(false);try{if(!audioContext)audioContext=new AudioContextType();if(audioContext.state==='running'){audioReady=true;updateSoundButton();return Promise.resolve(true);}return audioContext.resume().then(function(){audioReady=audioContext.state==='running';updateSoundButton();return audioReady;}).catch(function(){audioReady=false;updateSoundButton();return false;});}catch(error){audioReady=false;updateSoundButton();return Promise.resolve(false);}}
  function playTone(frequency,delay,duration,volume){if(!soundEnabled||!audioContext||audioContext.state!=='running')return;var start=audioContext.currentTime+delay,oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(volume,start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(start);oscillator.stop(start+duration+.03);}
  function playSentSound(){playTone(740,0,.1,.055);playTone(988,.085,.14,.045);}
  function playIncomingBell(){playTone(988,0,.32,.075);playTone(1480,.015,.27,.035);playTone(1318,.19,.38,.065);playTone(1977,.205,.29,.03);}
  function rememberMessages(messages){messages.forEach(function(message){var id=String(message.id||'');if(!id||knownMessageIds.has(id))return;knownMessageIds.add(id);if(message.direction==='inbound')playIncomingBell();else if(message.direction==='outbound'&&message.status!=='failed'&&message.status!=='uncertain')playSentSound();});}
  updateSoundButton();
  if(soundButton)soundButton.addEventListener('click',function(){if(soundEnabled&&audioReady){soundEnabled=false;try{window.localStorage.setItem('zapapi-chat-sounds','off');}catch(error){}updateSoundButton();return;}soundEnabled=true;try{window.localStorage.setItem('zapapi-chat-sounds','on');}catch(error){}unlockAudio().then(function(ready){if(ready)playIncomingBell();});});
  function unlockFromGesture(event){if(soundButton&&event.target instanceof Element&&event.target.closest('#sound-toggle'))return;unlockAudio();}
  document.addEventListener('pointerdown',unlockFromGesture,{passive:true});document.addEventListener('keydown',unlockFromGesture);
  if(!AudioContextType&&soundButton){soundButton.disabled=true;soundButton.textContent='Áudio indisponível';soundButton.title='Este navegador não oferece suporte ao áudio da conversa';}
  function node(tag,className,text){var item=document.createElement(tag);if(className)item.className=className;if(text!==undefined)item.textContent=text;return item;}
  function contactPhotoUrl(waId){var url=new URL('/painel/foto-contato',window.location.origin);url.searchParams.set('account_id',accountId);url.searchParams.set('wa_id',waId);return url.toString();}
  function setAvatar(avatar,label,hasPhoto,waId){var state=hasPhoto?'1':'0',avatarLabel=label||waId||'?';if(avatar.dataset.photoState===state&&avatar.dataset.avatarLabel===avatarLabel)return;var samePhoto=avatar.dataset.photoState===state&&hasPhoto;avatar.dataset.photoState=state;avatar.dataset.avatarLabel=avatarLabel;var initial=Array.from(avatarLabel)[0].toLocaleUpperCase('pt-BR');if(samePhoto&&avatar.querySelector('img')){avatar.firstChild.nodeValue=initial;return;}avatar.replaceChildren(document.createTextNode(initial));if(!hasPhoto)return;var image=node('img');image.alt='';image.loading='lazy';image.src=contactPhotoUrl(waId);image.addEventListener('error',function(){image.remove();},{once:true});avatar.appendChild(image);}
  document.querySelectorAll('.avatar img').forEach(function(image){image.addEventListener('error',function(){image.remove();},{once:true});});
  function urlFor(waId){var url=new URL('/painel/conversas',window.location.origin);url.searchParams.set('account_id',accountId);if(waId)url.searchParams.set('wa_id',waId);if(params.get('q'))url.searchParams.set('q',params.get('q'));if(params.get('status'))url.searchParams.set('status',params.get('status'));return url.toString();}
  function showFeedback(message,type){if(!feedback)return;feedback.hidden=!message;feedback.className='notice '+(type||'ok');feedback.textContent=message||'';}
  function renderConversations(rows){
    var fragment=document.createDocumentFragment();
    if(!rows.length){var empty=node('div','empty');empty.appendChild(node('b','', 'Nenhuma conversa ainda'));empty.appendChild(document.createTextNode('Quando alguém enviar mensagem, a conversa aparece aqui.'));fragment.appendChild(empty);}
    rows.forEach(function(row){var label=row.display_name||row.wa_id,a=node('a','convrow'+(selectedWa===row.wa_id?' selected':''));a.href=urlFor(row.wa_id);a.dataset.messageId=row.message_id;
      var avatar=node('span','avatar');setAvatar(avatar,label,row.has_photo,row.wa_id);a.appendChild(avatar);
      var main=node('span','convmain');main.appendChild(node('b','',label));main.appendChild(node('p','',row.preview));a.appendChild(main);
      var meta=node('span','convmeta');meta.appendChild(document.createTextNode(row.time_label));meta.appendChild(document.createElement('br'));meta.appendChild(document.createTextNode(row.closed?'Encerrada':'Aberta'));a.appendChild(meta);fragment.appendChild(a);
    });
    rowsBox.replaceChildren(fragment);
  }
  function conversationMediaUrl(mediaId){var url=new URL('/painel/midia',window.location.origin);url.searchParams.set('account_id',accountId);url.searchParams.set('wa_id',selectedWa);url.searchParams.set('id',mediaId);return url.toString();}
  function renderMessages(messages){
    if(!stream)return;
    var nearBottom=stream.scrollHeight-stream.scrollTop-stream.clientHeight<90,fragment=document.createDocumentFragment();
    var statusNames={accepted:'Enviada à Meta',sent:'Enviada',delivered:'Entregue',read:'Lida',failed:'Falhou',received:'Recebida'};
    if(!messages.length){var empty=node('div','empty');empty.appendChild(node('b','', 'Sem mensagens'));empty.appendChild(document.createTextNode('Envie um template aprovado para iniciar.'));fragment.appendChild(empty);}
    messages.forEach(function(message){var bubble=node('article','bubble'+(message.direction==='outbound'?' out':''));bubble.dataset.messageId=String(message.id||'');
      if(message.media_id){var src=conversationMediaUrl(message.media_id),type=message.message_type||'';
        if(type==='image'){var preview=node('button','media-preview');preview.type='button';preview.dataset.mediaOpen='image';preview.dataset.mediaSrc=src;preview.setAttribute('aria-label','Ampliar imagem');var image=node('img');image.src=src;image.alt='Imagem recebida';image.loading='lazy';image.decoding='async';preview.appendChild(image);bubble.appendChild(preview);}
        else if(type==='sticker'){var sticker=node('img','media-sticker');sticker.src=src;sticker.alt='Figurinha animada';sticker.loading='lazy';sticker.decoding='async';bubble.appendChild(sticker);}
        else if(type==='video'){var videoPreview=node('button','media-video-preview');videoPreview.type='button';videoPreview.dataset.mediaOpen='video';videoPreview.dataset.mediaSrc=src;videoPreview.setAttribute('aria-label','Reproduzir vídeo');var thumbnail=node('video');thumbnail.muted=true;thumbnail.playsInline=true;thumbnail.preload='metadata';thumbnail.src=src;videoPreview.appendChild(thumbnail);videoPreview.appendChild(node('span','media-play-icon','▶'));bubble.appendChild(videoPreview);}
        else if(type==='audio'){var audio=node('audio');audio.controls=true;audio.preload='metadata';audio.src=src;bubble.appendChild(audio);}
        else {var link=node('a','media-document',type==='document'?'Abrir documento':'Abrir anexo');link.href=src;link.target='_blank';link.rel='noreferrer';bubble.appendChild(link);}
        if(message.caption){var caption=node('div','',message.caption);caption.style.whiteSpace='pre-wrap';bubble.appendChild(caption);}}
      else {var body=node('div','',message.text);body.style.whiteSpace='pre-wrap';bubble.appendChild(body);}
      bubble.appendChild(node('time','',(message.time_label||'')+' · '+(statusNames[message.status]||message.status)));fragment.appendChild(bubble);
    });
    stream.replaceChildren(fragment);if(nearBottom||!stream.dataset.initialized)stream.scrollTop=stream.scrollHeight;stream.dataset.initialized='1';
  }
  var mediaDialog=document.querySelector('[data-media-modal]'),mediaContent=mediaDialog&&mediaDialog.querySelector('[data-media-modal-content]');
  function clearMediaDialog(){if(!mediaContent)return;mediaContent.querySelectorAll('video').forEach(function(video){video.pause();video.removeAttribute('src');video.load();});mediaContent.replaceChildren();}
  if(mediaDialog&&mediaContent){
    mediaDialog.querySelector('[data-media-close]').addEventListener('click',function(){mediaDialog.close();});
    mediaDialog.addEventListener('click',function(event){if(event.target===mediaDialog)mediaDialog.close();});
    mediaDialog.addEventListener('close',clearMediaDialog);
    if(stream)stream.addEventListener('click',function(event){var trigger=event.target.closest('[data-media-open]');if(!trigger||!mediaDialog.showModal)return;var kind=trigger.dataset.mediaOpen,src=trigger.dataset.mediaSrc;if(!src)return;clearMediaDialog();if(kind==='video'){var video=node('video');video.controls=true;video.autoplay=true;video.playsInline=true;video.preload='auto';video.src=src;mediaContent.appendChild(video);mediaDialog.showModal();var playback=video.play();if(playback&&playback.catch)playback.catch(function(){});}else if(kind==='image'){var image=node('img');image.src=src;image.alt='Imagem';mediaContent.appendChild(image);mediaDialog.showModal();}});
  }
  async function refresh(){
    if(refreshing||sending||document.visibilityState==='hidden')return;refreshing=true;
    try{
      var url=new URL('/painel/conversas/atualizacoes',window.location.origin);url.searchParams.set('account_id',accountId);if(selectedWa)url.searchParams.set('wa_id',selectedWa);if(params.get('q'))url.searchParams.set('q',params.get('q'));if(params.get('status'))url.searchParams.set('status',params.get('status'));
      var response=await fetch(url.toString(),{credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});
      if(new URL(response.url).pathname==='/entrar'){window.location.assign(response.url);return;}
      if(!response.ok)throw new Error('HTTP '+response.status);
      var data=await response.json();
      if(!selectedWa){var incoming=data.conversations.find(function(row){return row.direction==='inbound'&&!seenMessages.has(row.message_id);});if(incoming){playIncomingBell();window.setTimeout(function(){window.location.assign(urlFor(incoming.wa_id));},450);return;}}
      data.conversations.forEach(function(row){seenMessages.add(row.message_id);});
      var nextConversations=JSON.stringify(data.conversations);if(nextConversations!==conversationSignature){renderConversations(data.conversations);conversationSignature=nextConversations;}
      if(selectedWa&&data.selected_wa_id===selectedWa&&data.contact&&stream){var headerAvatar=document.querySelector('.chathead .avatar');if(headerAvatar)setAvatar(headerAvatar,data.contact.display_name||selectedWa,data.contact.has_photo,selectedWa);var nextMessages=JSON.stringify(data.messages);if(nextMessages!==messageSignature){rememberMessages(data.messages);renderMessages(data.messages);messageSignature=nextMessages;}}
    }catch(error){console.warn('Atualização automática da conversa falhou.',error);}
    finally{refreshing=false;}
  }
  document.querySelectorAll('[data-quick-reply]').forEach(function(select){select.addEventListener('change',function(){if(this.value){var field=document.querySelector('.composer textarea');if(field){field.value=this.value;field.focus();}}});});
  var composer=document.querySelector('.composer'),composerText=composer&&composer.querySelector('textarea'),fileInput=composer&&composer.querySelector('input[type="file"]'),fileName=composer&&composer.querySelector('[data-file-name]'),emojiToggle=composer&&composer.querySelector('[data-emoji-toggle]'),emojiPicker=composer&&composer.querySelector('[data-emoji-picker]');
  if(fileInput&&fileName)fileInput.addEventListener('change',function(){fileName.textContent=this.files&&this.files[0]?this.files[0].name:'';fileName.hidden=!fileName.textContent;});
  if(emojiToggle&&emojiPicker){emojiToggle.addEventListener('click',function(){var open=emojiPicker.hidden;emojiPicker.hidden=!open;emojiToggle.setAttribute('aria-expanded',String(open));});emojiPicker.addEventListener('click',function(event){var button=event.target.closest('[data-emoji]');if(!button||!composerText)return;var emoji=button.dataset.emoji,start=composerText.selectionStart,end=composerText.selectionEnd;composerText.setRangeText(emoji,start,end,'end');composerText.focus();emojiPicker.hidden=true;emojiToggle.setAttribute('aria-expanded','false');});document.addEventListener('pointerdown',function(event){if(!composer.contains(event.target)){emojiPicker.hidden=true;emojiToggle.setAttribute('aria-expanded','false');}});}
  if(composerText)composerText.addEventListener('keydown',function(event){if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();var submitButton=composer.querySelector('button[type="submit"]');if(!submitButton||!submitButton.disabled){if(composer.requestSubmit)composer.requestSubmit();}}});
  if(stream)stream.scrollTop=stream.scrollHeight;
  if(composer)composer.addEventListener('submit',async function(event){
    event.preventDefault();if(sending)return;sending=true;var button=composer.querySelector('button[type="submit"]'),original=button?button.textContent:'Enviar →';if(button){button.disabled=true;button.textContent='Enviando…';}showFeedback('Enviando mensagem à Meta…','ok');
    try{
      var response=await fetch(composer.getAttribute('action')||window.location.href,{method:'POST',body:new FormData(composer),credentials:'same-origin',cache:'no-store',headers:{'X-Requested-With':'XMLHttpRequest'}}),html=await response.text();
      if(new URL(response.url).pathname==='/entrar'){window.location.assign(response.url);return;}
      if(!response.ok){var parsed=new DOMParser().parseFromString(html,'text/html'),alert=parsed.querySelector('[role="alert"]');throw new Error(alert?alert.textContent.trim():'Não foi possível confirmar o envio.');}
      var parsedSuccess=new DOMParser().parseFromString(html,'text/html'),sendError=parsedSuccess.querySelector('[role="alert"]');if(sendError)throw new Error(sendError.textContent.trim());
      var textarea=composer.querySelector('textarea'),file=composer.querySelector('input[type="file"]');if(textarea)textarea.value='';if(file)file.value='';if(fileName){fileName.textContent='';fileName.hidden=true;}showFeedback('Mensagem enviada à Meta. O status de entrega será atualizado automaticamente.','ok');
      await refresh();
    }catch(error){showFeedback(error.message||'Não foi possível enviar a mensagem. Confira o chat antes de tentar novamente.','bad');await refresh();}
    finally{sending=false;if(button){button.disabled=false;button.textContent=original;}refresh();}
  });
  refresh();setInterval(refresh,2000);document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')refresh();});
})();
</script><?php endif; ?>
<?php if($page==='new'): ?><script>
(function(){var select=document.getElementById('template-choice'),box=document.getElementById('template-parameters'),lang=document.getElementById('template-language');if(!select)return;function render(){var op=select.options[select.selectedIndex];if(!op)return;lang.value=op.dataset.language||'';var header=Number(op.dataset.headerVars||0),body=Number(op.dataset.bodyVars||0);box.replaceChildren();box.hidden=!(header||body);function group(type,count,label){if(!count)return;var h=document.createElement('h3');h.textContent=label;box.appendChild(h);for(var i=1;i<=count;i++){var wrap=document.createElement('div');wrap.className='field';var l=document.createElement('label');var id=type+'-'+i;l.htmlFor=id;l.textContent='Variável {{'+i+'}}';var input=document.createElement('input');input.id=id;input.name=type+'_params[]';input.required=true;input.maxLength=1024;input.placeholder='Valor para o contato';wrap.appendChild(l);wrap.appendChild(input);box.appendChild(wrap);}}group('header',header,'Cabeçalho');group('body',body,'Mensagem');}select.addEventListener('change',render);render();})();
</script><?php endif; ?>
<?php if($page==='campaigns'): ?><script>
(function(){var s=document.getElementById('campaign-template'),l=document.getElementById('campaign-language');function sync(){if(s&&l){var o=s.options[s.selectedIndex];l.value=o?o.dataset.language:'';}}if(s){s.addEventListener('change',sync);sync();}var all=document.querySelector('[data-select-all]');if(all)all.addEventListener('click',function(){document.querySelectorAll('input[name="contact_ids[]"]').forEach(function(c){c.checked=true;});});})();
</script><?php endif; ?>
